"""Sanic Blueprint exposing A2A JSON-RPC routes on the main Rasa server.

This module replaces the Starlette HTTP adapter layer from ``a2a-sdk``'s
``JSONRPCApplication._handle_requests`` with a Sanic-native equivalent,
while reusing the transport-agnostic ``JSONRPCHandler`` and
``DefaultRequestHandler`` from the SDK unchanged.

Route layout (registered at root, no URL prefix):
  POST /                           — A2A JSON-RPC endpoint
  GET  /.well-known/agent-card.json — public AgentCard
  GET  /.well-known/agent.json      — deprecated AgentCard alias
"""

from __future__ import annotations

import asyncio
import json
from typing import TYPE_CHECKING, Any, AsyncGenerator

import structlog
from a2a.auth.user import UnauthenticatedUser
from a2a.auth.user import User as A2AUser
from a2a.extensions.common import HTTP_EXTENSION_HEADER, get_requested_extensions
from a2a.server.apps.jsonrpc.jsonrpc_app import JSONRPCApplication
from a2a.server.context import ServerCallContext
from a2a.server.request_handlers.response_helpers import prepare_response_object
from a2a.types import (
    A2AError,
    A2ARequest,
    InternalError,
    InvalidParamsError,
    InvalidRequestError,
    JSONParseError,
    JSONRPCErrorResponse,
    JSONRPCRequest,
    Message,
    MethodNotFoundError,
    SendStreamingMessageRequest,
    SendStreamingMessageResponse,
    SendStreamingMessageSuccessResponse,
    Task,
    TaskArtifactUpdateEvent,
    TaskResubscriptionRequest,
    TaskStatusUpdateEvent,
)
from a2a.utils.constants import (
    AGENT_CARD_WELL_KNOWN_PATH,
    DEFAULT_RPC_URL,
    PREV_AGENT_CARD_WELL_KNOWN_PATH,
)
from a2a.utils.errors import MethodNotImplementedError, ServerError
from pydantic import ValidationError
from sanic import Blueprint
from sanic.request import Request
from sanic.response import HTTPResponse, ResponseStream
from sanic.response import json as sanic_json

from rasa.core.a2a_server.auth import (
    A2A_UNAUTHORIZED_RESPONSE_BODY,
    A2AAuthenticatedUser,
    A2ABearerAuthValidator,
    a2a_bearer_unauthorized_response_headers,
)
from rasa.core.a2a_server.errors import A2AMessageInFlightConflict
from rasa.core.a2a_server.rasa_a2a_request_handler import RasaA2ARequestHandler

if TYPE_CHECKING:
    from a2a.server.request_handlers.jsonrpc_handler import JSONRPCHandler
    from a2a.types import AgentCard
    from sanic import Sanic

structlogger = structlog.get_logger()

_MAX_CONTENT_LENGTH = 10 * 1024 * 1024  # 10 MB — matches JSONRPCApplication default


def _build_server_call_context(request: Request) -> ServerCallContext:
    """Build a ``ServerCallContext`` from a Sanic request.

    When bearer auth is configured and the request passed validation, the user
    is an ``A2AAuthenticatedUser``. Otherwise, the user is ``UnauthenticatedUser``.
    Header state and extension negotiation match ``DefaultCallContextBuilder``.
    """
    headers = {
        key: value
        for key, value in request.headers.items()
        if key.lower() != "authorization"
    }
    extension_values = request.headers.getall(HTTP_EXTENSION_HEADER, [])
    auth_payload = getattr(request.ctx, "a2a_auth_payload", None)
    user: A2AUser
    state: dict[str, Any]
    if auth_payload is not None:
        user = A2AAuthenticatedUser(auth_payload)
        state = {"auth": auth_payload, "headers": headers}
    else:
        user = UnauthenticatedUser()
        state = {"headers": headers}
    return ServerCallContext(
        user=user,
        state=state,
        requested_extensions=get_requested_extensions(extension_values),
    )


def _unauthorized_response() -> HTTPResponse:
    """Return HTTP 401 for missing or invalid orchestrator bearer credentials."""
    return sanic_json(
        A2A_UNAUTHORIZED_RESPONSE_BODY,
        status=401,
        headers=a2a_bearer_unauthorized_response_headers(),
    )


def _validate_a2a_bearer_auth(request: Request) -> HTTPResponse | None:
    """Validate bearer JWT when auth is configured on the A2A server.

    Returns an HTTP 401 response with ``WWW-Authenticate: Bearer`` when
    validation fails. When auth is not configured, or validation succeeds,
    returns ``None``.
    """
    validator: A2ABearerAuthValidator | None = getattr(
        request.app.ctx, "a2a_bearer_auth_validator", None
    )
    if validator is None:
        return None

    jwt_payload = validator.validate_authorization_header(
        request.headers.get("Authorization")
    )
    if jwt_payload is None:
        structlogger.debug(
            "a2a_server.sanic_app.auth_rejected",
            path=request.path,
        )
        return _unauthorized_response()

    request.ctx.a2a_auth_payload = jwt_payload
    return None


def _extract_request_id(body: Any) -> str | int | None:
    """Read a JSON-RPC ``id`` from a parsed request body, if present."""
    if isinstance(body, dict):
        raw_id = body.get("id")
        if isinstance(raw_id, str | int):
            return raw_id
    return None


def _payload_too_large_response(request: Request) -> HTTPResponse | None:
    """Return an error response when ``Content-Length`` exceeds the limit."""
    try:
        content_length = int(request.headers.get("content-length", "0"))
    except ValueError:
        return None
    if content_length and content_length > _MAX_CONTENT_LENGTH:
        return _jsonrpc_error_response(
            None,
            A2AError(root=InvalidRequestError(message="Payload too large")),
        )
    return None


def _parse_json_body(
    request: Request,
) -> tuple[HTTPResponse | None, Any, str | int | None]:
    """Parse the POST body as JSON.

    Returns ``(error_response, body, request_id)``. When ``error_response`` is
    set, ``body`` and ``request_id`` are not used.
    """
    try:
        body = request.json
    except Exception as exc:
        return (
            _jsonrpc_error_response(
                None, A2AError(root=JSONParseError(message=str(exc)))
            ),
            None,
            None,
        )

    if body is None:
        return (
            _jsonrpc_error_response(
                None,
                A2AError(root=JSONParseError(message="Empty or non-JSON body")),
            ),
            None,
            None,
        )

    return None, body, _extract_request_id(body)


def _validate_a2a_request(
    body: Any,
    request_id: str | int | None,
) -> tuple[HTTPResponse | None, A2ARequest | None, str | int | None, str | None]:
    """Validate JSON-RPC framing and build a typed ``A2ARequest``.

    Returns ``(error_response, a2a_request, request_id, method)``.
    """
    try:
        base_request = JSONRPCRequest.model_validate(body)
    except ValidationError as exc:
        return (
            _jsonrpc_error_response(
                request_id,
                A2AError(root=InvalidRequestError(data=json.loads(exc.json()))),
            ),
            None,
            request_id,
            None,
        )

    method = base_request.method
    model_class = JSONRPCApplication.METHOD_TO_MODEL.get(method)
    if not model_class:
        return (
            _jsonrpc_error_response(request_id, A2AError(root=MethodNotFoundError())),
            None,
            request_id,
            None,
        )

    try:
        specific_request = model_class.model_validate(body)
    except ValidationError as exc:
        return (
            _jsonrpc_error_response(
                request_id,
                A2AError(root=InvalidParamsError(data=json.loads(exc.json()))),
            ),
            None,
            request_id,
            None,
        )

    request_id = specific_request.id
    return None, A2ARequest(root=specific_request), request_id, method


def _activated_extension_headers(context: ServerCallContext) -> dict[str, str]:
    if exts := context.activated_extensions:
        return {HTTP_EXTENSION_HEADER: ", ".join(sorted(exts))}
    return {}


def _jsonrpc_result_response(
    result: Any,
    extra_headers: dict[str, str],
) -> HTTPResponse:
    """Serialise a JSON-RPC success or handler error payload."""
    if isinstance(result, JSONRPCErrorResponse):
        payload = result.model_dump(mode="json", exclude_none=True)
    else:
        payload = result.root.model_dump(mode="json", exclude_none=True)
    return sanic_json(payload, headers=extra_headers, status=200)


def _jsonrpc_error_response(
    request_id: str | int | None,
    error: A2AError,
    *,
    http_status: int = 200,
) -> HTTPResponse:
    """Serialise a JSON-RPC error payload as a Sanic response."""
    error_resp = JSONRPCErrorResponse(
        id=request_id,
        error=error.root,
    )
    if isinstance(error.root, InternalError):
        structlogger.error(
            "a2a_server.sanic_app.request_error",
            request_id=request_id,
            code=error_resp.error.code,
            message=error_resp.error.message,
            http_status=http_status,
        )
    else:
        structlogger.warning(
            "a2a_server.sanic_app.request_error",
            request_id=request_id,
            code=error_resp.error.code,
            message=error_resp.error.message,
            http_status=http_status,
        )
    return sanic_json(
        error_resp.model_dump(mode="json", exclude_none=True),
        status=http_status,
    )


def _jsonrpc_in_flight_conflict_response(
    request_id: str | int | None,
    exc: A2AMessageInFlightConflict,
) -> HTTPResponse:
    """Return HTTP 409 for duplicate ``messageId`` while the first request runs."""
    structlogger.warning(
        "a2a_server.sanic_app.message_in_flight_conflict",
        request_id=request_id,
        context_id=exc.context_id,
        message_id=exc.message_id,
    )
    return _jsonrpc_error_response(
        request_id,
        A2AError(
            root=InvalidParamsError(
                message=(
                    f"message_id {exc.message_id!r} is already in flight "
                    f"for context {exc.context_id!r}"
                )
            )
        ),
        http_status=409,
    )


async def _wrap_message_stream_for_jsonrpc(
    request_id: str | int | None,
    event_stream: AsyncGenerator[Any, None],
) -> AsyncGenerator[SendStreamingMessageResponse, None]:
    """Wrap handler events as ``SendStreamingMessageResponse`` for SSE encoding."""
    async for event in event_stream:
        yield prepare_response_object(
            request_id,
            event,
            (
                Task,
                Message,
                TaskArtifactUpdateEvent,
                TaskStatusUpdateEvent,
            ),
            SendStreamingMessageSuccessResponse,
            SendStreamingMessageResponse,
        )


def _server_error_json_response(
    request_id: str | int | None,
    exc: ServerError,
) -> HTTPResponse:
    """Map a handler ``ServerError`` to a JSON-RPC error HTTP response."""
    error = exc.error if exc.error is not None else InternalError()
    return _jsonrpc_error_response(request_id, A2AError(root=error))


async def _prepend_stream_item(
    first_item: SendStreamingMessageResponse,
    stream: AsyncGenerator[SendStreamingMessageResponse, None],
) -> AsyncGenerator[SendStreamingMessageResponse, None]:
    """Re-yield a primed first item, then continue with the remaining stream."""
    yield first_item
    async for item in stream:
        yield item


def _empty_sse_stream() -> AsyncGenerator[SendStreamingMessageResponse, None]:
    """Return a fresh async generator that yields no SSE events."""

    async def async_generator() -> AsyncGenerator[SendStreamingMessageResponse, None]:
        await asyncio.sleep(0)
        if False:
            yield SendStreamingMessageResponse

    return async_generator()


async def _prepare_sse_response(
    stream_gen: AsyncGenerator[SendStreamingMessageResponse, None],
    call_context: ServerCallContext,
    *,
    request_id: str | int | None,
) -> HTTPResponse | ResponseStream:
    """Prime ``stream_gen`` so setup errors become JSON-RPC before SSE headers.

    If the first stream item is already a JSON-RPC error envelope, return it as
    a normal JSON response instead of opening an SSE stream.
    """
    try:
        first_item = await anext(stream_gen)
    except StopAsyncIteration:
        return _create_sse_response(_empty_sse_stream(), call_context)
    except ServerError as exc:
        return _server_error_json_response(request_id, exc)

    if isinstance(first_item.root, JSONRPCErrorResponse):
        try:
            await stream_gen.aclose()
        except Exception:
            pass
        return _jsonrpc_result_response(
            first_item.root,
            _activated_extension_headers(call_context),
        )

    return _create_sse_response(
        _prepend_stream_item(first_item, stream_gen),
        call_context,
    )


def _create_sse_response(
    async_gen: AsyncGenerator[SendStreamingMessageResponse, None],
    context: ServerCallContext,
) -> ResponseStream:
    """Return a Sanic ``ResponseStream`` that encodes A2A events as SSE.

    Returning ``ResponseStream`` (instead of calling ``request.respond()`` and
    returning ``None``) lets Sanic finish the HTTP lifecycle correctly under
    ASGI: after the first chunk, ASGI clears ``request.stream.response``, so a
    ``None`` return triggers ``Invalid response type None``.
    """
    extra_headers: dict[str, str] = {}
    if exts := context.activated_extensions:
        extra_headers[HTTP_EXTENSION_HEADER] = ", ".join(sorted(exts))

    async def stream_sse(resp: ResponseStream) -> None:
        try:
            async for item in async_gen:
                await resp.write(
                    f"data: {item.root.model_dump_json(exclude_none=True)}\n\n"
                )
        except Exception:
            structlogger.exception("a2a_server.sanic_app.stream_sse.error")

    return ResponseStream(
        stream_sse,
        content_type="text/event-stream",
        headers={
            "Cache-Control": "no-cache",
            "X-Accel-Buffering": "no",
            **extra_headers,
        },
    )


async def _execute_jsonrpc_request(
    handler: Any,
    a2a_request: A2ARequest,
    call_context: ServerCallContext,
) -> HTTPResponse | ResponseStream | None:
    """Dispatch a validated request; stream or return a JSON-RPC HTTP response."""
    request_obj = a2a_request.root
    request_id = a2a_request.root.id

    try:
        return await _execute_jsonrpc_request_inner(
            handler, a2a_request, call_context, request_obj, request_id
        )
    except A2AMessageInFlightConflict as exc:
        return _jsonrpc_in_flight_conflict_response(request_id, exc)
    except ServerError as exc:
        return _server_error_json_response(request_id, exc)


async def _execute_jsonrpc_request_inner(
    handler: Any,
    a2a_request: A2ARequest,
    call_context: ServerCallContext,
    request_obj: Any,
    request_id: str | int | None,
) -> HTTPResponse | ResponseStream | None:
    if isinstance(request_obj, SendStreamingMessageRequest):
        req_handler = getattr(handler, "request_handler", None)
        if isinstance(req_handler, RasaA2ARequestHandler):
            event_stream = await req_handler.build_message_send_stream(
                request_obj.params, call_context
            )
            stream_gen = _wrap_message_stream_for_jsonrpc(request_id, event_stream)
        else:
            stream_gen = handler.on_message_send_stream(request_obj, call_context)
        return await _prepare_sse_response(
            stream_gen,
            call_context,
            request_id=request_id,
        )

    if isinstance(request_obj, TaskResubscriptionRequest):
        return await _prepare_sse_response(
            handler.on_resubscribe_to_task(request_obj, call_context),
            call_context,
            request_id=request_id,
        )

    result = await _dispatch_non_streaming(handler, a2a_request, call_context)
    return _jsonrpc_result_response(result, _activated_extension_headers(call_context))


def agent_card_payload(card: "AgentCard") -> dict[str, Any]:
    """Serialize an ``AgentCard`` for the public GET endpoints."""
    return card.model_dump(exclude_none=True, by_alias=True)


def set_a2a_agent_card_ctx(app: "Sanic", card: "AgentCard") -> None:
    """Store the runtime card and its serialized payload on ``app.ctx``."""
    app.ctx.a2a_agent_card = card
    app.ctx.a2a_agent_card_payload = agent_card_payload(card)


def create_a2a_blueprint() -> Blueprint:
    """Return a Sanic ``Blueprint`` that serves the A2A protocol.

    The blueprint has no URL prefix so its routes sit at the server root,
    matching the standard A2A path layout:
      POST /                            JSON-RPC
      GET  /.well-known/agent-card.json AgentCard
      GET  /.well-known/agent.json      AgentCard (deprecated alias)

    Route handlers access ``request.app.ctx.a2a_jsonrpc_handler`` and
    ``request.app.ctx.a2a_agent_card_payload`` at request time. Callers must
    set the payload when registering the blueprint (placeholder card) and
    again at ``after_server_start`` when the runtime card is resolved.
    """
    bp = Blueprint("a2a", url_prefix="")

    def _agent_card_response(request: Request) -> HTTPResponse:
        return sanic_json(request.app.ctx.a2a_agent_card_payload, status=200)

    def _serve_agent_card_if_authorized(request: Request) -> HTTPResponse:
        if auth_error := _validate_a2a_bearer_auth(request):
            return auth_error
        return _agent_card_response(request)

    # ------------------------------------------------------------------ #
    # JSON-RPC endpoint                                                    #
    # ------------------------------------------------------------------ #

    @bp.post(DEFAULT_RPC_URL)
    async def handle_jsonrpc(request: Request) -> HTTPResponse | ResponseStream | None:
        """Handle all A2A JSON-RPC requests.

        Replicates the routing logic from
        ``JSONRPCApplication._handle_requests`` for Sanic, delegating the
        transport-agnostic dispatch to ``JSONRPCHandler``.
        """
        request_id: str | int | None = None

        try:
            if too_large := _payload_too_large_response(request):
                return too_large

            if auth_error := _validate_a2a_bearer_auth(request):
                return auth_error

            parse_error, body, request_id = _parse_json_body(request)
            if parse_error is not None:
                return parse_error

            structlogger.debug("a2a_server.sanic_app.handle_jsonrpc.body", body=body)

            validation_error, a2a_request, request_id, method = _validate_a2a_request(
                body, request_id
            )
            if validation_error is not None or a2a_request is None or method is None:
                return validation_error

            call_context = _build_server_call_context(request)
            call_context.state["method"] = method

            handler = request.app.ctx.a2a_jsonrpc_handler
            return await _execute_jsonrpc_request(handler, a2a_request, call_context)

        except MethodNotImplementedError:
            structlogger.exception(
                "a2a_server.sanic_app.handle_jsonrpc.method_not_implemented"
            )
            from a2a.types import UnsupportedOperationError

            return _jsonrpc_error_response(
                request_id,
                A2AError(root=UnsupportedOperationError()),
            )
        except Exception as exc:
            structlogger.exception(
                "a2a_server.sanic_app.handle_jsonrpc.unhandled_error",
                exception=str(exc),
            )
            return _jsonrpc_error_response(
                request_id,
                A2AError(root=InternalError(message="Internal server error")),
            )

    # ------------------------------------------------------------------ #
    # AgentCard endpoints                                                  #
    # ------------------------------------------------------------------ #

    @bp.get(AGENT_CARD_WELL_KNOWN_PATH)
    async def serve_agent_card(request: Request) -> HTTPResponse:
        """Serve the AgentCard when bearer auth passes (if configured)."""
        return _serve_agent_card_if_authorized(request)

    @bp.get(PREV_AGENT_CARD_WELL_KNOWN_PATH)
    async def serve_agent_card_deprecated(request: Request) -> HTTPResponse:
        """Serve the AgentCard at the deprecated path when bearer auth passes."""
        structlogger.warning(
            "a2a_server.sanic_app.agent_card_deprecated_endpoint",
            deprecated_path=PREV_AGENT_CARD_WELL_KNOWN_PATH,
            preferred_path=AGENT_CARD_WELL_KNOWN_PATH,
        )
        return _serve_agent_card_if_authorized(request)

    return bp


# ------------------------------------------------------------------ #
# Internal dispatch helper                                            #
# ------------------------------------------------------------------ #


async def _dispatch_non_streaming(
    handler: JSONRPCHandler,
    a2a_request: A2ARequest,
    context: ServerCallContext,
) -> Any:
    """Delegate a non-streaming ``A2ARequest`` to the correct
    ``JSONRPCHandler`` method."""
    from a2a.types import (
        CancelTaskRequest,
        DeleteTaskPushNotificationConfigRequest,
        GetAuthenticatedExtendedCardRequest,
        GetTaskPushNotificationConfigRequest,
        GetTaskRequest,
        ListTaskPushNotificationConfigRequest,
        SendMessageRequest,
        SetTaskPushNotificationConfigRequest,
        UnsupportedOperationError,
    )

    request_obj = a2a_request.root

    match request_obj:
        case SendMessageRequest():
            return await handler.on_message_send(request_obj, context)
        case CancelTaskRequest():
            return await handler.on_cancel_task(request_obj, context)
        case GetTaskRequest():
            return await handler.on_get_task(request_obj, context)
        case SetTaskPushNotificationConfigRequest():
            return await handler.set_push_notification_config(request_obj, context)
        case GetTaskPushNotificationConfigRequest():
            return await handler.get_push_notification_config(request_obj, context)
        case ListTaskPushNotificationConfigRequest():
            return await handler.list_push_notification_config(request_obj, context)
        case DeleteTaskPushNotificationConfigRequest():
            return await handler.delete_push_notification_config(request_obj, context)
        case GetAuthenticatedExtendedCardRequest():
            return await handler.get_authenticated_extended_card(request_obj, context)
        case _:
            structlogger.error(
                "a2a_server.sanic_app.dispatch.unknown_request_type",
                request_type=type(request_obj).__name__,
            )
            return JSONRPCErrorResponse(
                id=a2a_request.root.id,
                error=UnsupportedOperationError(
                    message=f"Request type {type(request_obj).__name__} is unknown."
                ),
            )
